import java.math.*;import java.util.*;
public class RSA{public static void main(String[]x){Scanner s=new Scanner(System.in);System.out.print("Enter first prime p: ");BigInteger p=s.nextBigInteger();System.out.print("Enter second prime q: ");BigInteger q=s.nextBigInteger();if(!p.isProbablePrime(20)||!q.isProbablePrime(20)||p.equals(q))throw new IllegalArgumentException("Enter two different prime numbers.");BigInteger n=p.multiply(q),phi=p.subtract(BigInteger.ONE).multiply(q.subtract(BigInteger.ONE)),e=BigInteger.TWO;while(!e.gcd(phi).equals(BigInteger.ONE))e=e.add(BigInteger.ONE);BigInteger d=e.modInverse(phi);System.out.print("Enter numeric message (0 <= m < "+n+"): ");BigInteger m=s.nextBigInteger();if(m.signum()<0||m.compareTo(n)>=0)throw new IllegalArgumentException("Message out of range.");BigInteger ct=m.modPow(e,n);System.out.println("Public Key: "+n);System.out.println("Exponent: "+e);System.out.println("Private Key: "+d);System.out.println("Cipher Text: "+ct);System.out.println("Decrypted Message: "+ct.modPow(d,n));}}
